import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DYAmjhAm.js";const u=JSON.parse('{"title":"Interface: DataServiceAdapter","description":"","frontmatter":{},"headers":[],"relativePath":"api/interfaces/DataServiceAdapter.md","filePath":"api/interfaces/DataServiceAdapter.md","lastUpdated":null}'),i={name:"api/interfaces/DataServiceAdapter.md"};function n(s,e,d,c,h,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">breeze-client</a> / DataServiceAdapter</p><h1 id="interface-dataserviceadapter" tabindex="-1">Interface: DataServiceAdapter <a class="header-anchor" href="#interface-dataserviceadapter" aria-label="Permalink to &quot;Interface: DataServiceAdapter&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/interface-registry.ts#L106" target="_blank" rel="noreferrer">src/config/interface-registry.ts:106</a></p><p>Reshapes data moving between breeze and server</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to &quot;Extends&quot;">​</a></h2><ul><li><a href="./BaseAdapter"><code>BaseAdapter</code></a></li></ul><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="changerequestinterceptor" tabindex="-1">changeRequestInterceptor <a class="header-anchor" href="#changerequestinterceptor" aria-label="Permalink to &quot;changeRequestInterceptor&quot;">​</a></h3><blockquote><p><strong>changeRequestInterceptor</strong>: <a href="./ChangeRequestInterceptorCtor"><code>ChangeRequestInterceptorCtor</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/interface-registry.ts#L131" target="_blank" rel="noreferrer">src/config/interface-registry.ts:131</a></p><p>The constructor of the <a href="./ChangeRequestInterceptor">ChangeRequestInterceptor</a> the adapter creates for each save, to let an application change each entity&#39;s save request and the finished array of requests without writing its own adapter. Defaults to a no-op interceptor.</p><hr><h3 id="checkforrecomposition" tabindex="-1">checkForRecomposition? <a class="header-anchor" href="#checkforrecomposition" aria-label="Permalink to &quot;checkForRecomposition?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>checkForRecomposition?</strong>: (<code>context</code>) =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/config.ts#L96" target="_blank" rel="noreferrer">src/config/config.ts:96</a></p><p>Optional. Called each time any adapter is initialized after this one first was, with <code>{ interfaceName, instance, isDefault }</code>, so that this adapter can pick up a new dependency. The data service adapters use it to re-resolve their ajax adapter when a new default ajax adapter is initialized.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="context" tabindex="-1">context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;context&quot;">​</a></h5><p><code>any</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><h4 id="inherited-from" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./BaseAdapter"><code>BaseAdapter</code></a>.<a href="./BaseAdapter#checkforrecomposition"><code>checkForRecomposition</code></a></p><hr><h3 id="jsonresultsadapter" tabindex="-1">jsonResultsAdapter <a class="header-anchor" href="#jsonresultsadapter" aria-label="Permalink to &quot;jsonResultsAdapter&quot;">​</a></h3><blockquote><p><strong>jsonResultsAdapter</strong>: <a href="./../classes/JsonResultsAdapter"><code>JsonResultsAdapter</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/interface-registry.ts#L136" target="_blank" rel="noreferrer">src/config/interface-registry.ts:136</a></p><p>The <a href="./../classes/JsonResultsAdapter">JsonResultsAdapter</a> used to read this adapter&#39;s query and save results, unless the <a href="./../classes/DataService">DataService</a> names one of its own.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/config.ts#L84" target="_blank" rel="noreferrer">src/config/config.ts:84</a></p><p>The name the adapter is registered under, such as <code>&#39;webApi&#39;</code> or <code>&#39;backingStore&#39;</code>. Names are matched without regard to case. <code>registerAdapter</code> reads it from a throwaway instance and throws if it is empty.</p><h4 id="inherited-from-1" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-1" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./BaseAdapter"><code>BaseAdapter</code></a>.<a href="./BaseAdapter#name"><code>name</code></a></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="executequery" tabindex="-1">executeQuery() <a class="header-anchor" href="#executequery" aria-label="Permalink to &quot;executeQuery()&quot;">​</a></h3><blockquote><p><strong>executeQuery</strong>(<code>mappingContext</code>): <code>Promise</code>&lt;<a href="./QueryResult"><code>QueryResult</code></a>&lt;<code>any</code>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/interface-registry.ts#L119" target="_blank" rel="noreferrer">src/config/interface-registry.ts:119</a></p><p>Sends the query in <code>mappingContext</code> to the server. Resolves with the raw results, the inline count if one was asked for, and the <code>httpResponse</code>; Breeze then merges the results into the cache through the <a href="./../classes/JsonResultsAdapter">JsonResultsAdapter</a>.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="mappingcontext" tabindex="-1">mappingContext <a class="header-anchor" href="#mappingcontext" aria-label="Permalink to &quot;mappingContext&quot;">​</a></h5><p><code>MappingContext</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./QueryResult"><code>QueryResult</code></a>&lt;<code>any</code>&gt;&gt;</p><hr><h3 id="fetchmetadata" tabindex="-1">fetchMetadata() <a class="header-anchor" href="#fetchmetadata" aria-label="Permalink to &quot;fetchMetadata()&quot;">​</a></h3><blockquote><p><strong>fetchMetadata</strong>(<code>metadataStore</code>, <code>dataService</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/interface-registry.ts#L113" target="_blank" rel="noreferrer">src/config/interface-registry.ts:113</a></p><p>Fetches the metadata for a service and imports it into the <code>MetadataStore</code>. Called by <code>MetadataStore.fetchMetadata</code>, and before the first query to a service that has server metadata. Resolves with the raw metadata, or with a string saying why there is none (for example, that another request already fetched it). Rejects with the server error if the request fails.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="metadatastore" tabindex="-1">metadataStore <a class="header-anchor" href="#metadatastore" aria-label="Permalink to &quot;metadataStore&quot;">​</a></h5><p><a href="./../classes/MetadataStore"><code>MetadataStore</code></a></p><h5 id="dataservice" tabindex="-1">dataService <a class="header-anchor" href="#dataservice" aria-label="Permalink to &quot;dataService&quot;">​</a></h5><p><a href="./../classes/DataService"><code>DataService</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><hr><h3 id="initialize" tabindex="-1">initialize() <a class="header-anchor" href="#initialize" aria-label="Permalink to &quot;initialize()&quot;">​</a></h3><blockquote><p><strong>initialize</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/config.ts#L90" target="_blank" rel="noreferrer">src/config/config.ts:90</a></p><p>Called by Breeze each time the adapter is initialized: when it is first created, and again whenever it is initialized by name or registered again, for example by <a href="./../functions/configureBreeze">configureBreeze</a>. Resolve anything the adapter depends on here, not in the constructor.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><h4 id="inherited-from-2" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-2" aria-label="Permalink to &quot;Inherited from&quot;">​</a></h4><p><a href="./BaseAdapter"><code>BaseAdapter</code></a>.<a href="./BaseAdapter#initialize"><code>initialize</code></a></p><hr><h3 id="savechanges" tabindex="-1">saveChanges() <a class="header-anchor" href="#savechanges" aria-label="Permalink to &quot;saveChanges()&quot;">​</a></h3><blockquote><p><strong>saveChanges</strong>(<code>saveContext</code>, <code>saveBundle</code>): <code>Promise</code>&lt;<a href="./SaveResult"><code>SaveResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/25a2a3de2579496e809bd5b2d115b9a4a453672d/src/config/interface-registry.ts#L125" target="_blank" rel="noreferrer">src/config/interface-registry.ts:125</a></p><p>Sends the entities in <code>saveBundle</code> to the server and resolves with the saved entities and any key mappings. Called by <code>EntityManager.saveChanges</code>. Rejects with the server error, including any per-entity errors, if the save fails.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="savecontext" tabindex="-1">saveContext <a class="header-anchor" href="#savecontext" aria-label="Permalink to &quot;saveContext&quot;">​</a></h5><p><code>SaveContext</code></p><h5 id="savebundle" tabindex="-1">saveBundle <a class="header-anchor" href="#savebundle" aria-label="Permalink to &quot;saveBundle&quot;">​</a></h5><p><code>SaveBundle</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./SaveResult"><code>SaveResult</code></a>&gt;</p>',78)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
